def main():
    root = Path(__file__).resolve().parent
    raw = zlib.decompress(base64.b85decode(PAYLOAD.encode("ascii")))
    with tempfile.TemporaryDirectory(prefix="hunter_arena_") as td:
        engine_dir = Path(td) / "engine"
        engine_dir.mkdir()
        bundle = engine_dir / "engine.zip"
        bundle.write_bytes(raw)
        with zipfile.ZipFile(bundle) as z:
            z.extractall(engine_dir)
        bundle.unlink(missing_ok=True)
        sys.path.insert(0, str(engine_dir))
        try:
            runpy.run_path(str(engine_dir / "arena.py"), run_name="__main__")
        finally:
            try:
                sys.path.remove(str(engine_dir))
            except ValueError:
                pass

if __name__ == "__main__":
    main()
